-- Generated by tools/quest_gate/new_quest.py from Quest Helper's
-- helpers/quests/merlinscrystal/ -- docs/QUEST_SUITE_KIT.md phase 3.
-- Rewritten by hand against the quest's .rs2 and the guide.
-- quest test. Tier (quest_inventory.tsv): 3.
-- Items from getItemRequirements(): bread and gear are given in setup.
-- Setup always starts with ::clearinv: the fresh character carries fourteen
-- slots of tutorial kit that block a non-stackable requirement fitting in the backpack.
-- Rewards from Quest Helper: 0 experience, 1 item, quest points 6 (QuestPointReward).
--
-- Door rule (re-driven b61, docs/QUEST_ORCHESTRATOR.md standing rules): no goto_tile
-- enters or leaves a closed space. Every door, gate, stair and ladder is pressed on
-- every visit through the driver's verbs (pass_door / cross_gate / climb), graded on
-- the tiles; long trips are REAL teleports (teleport_cast: cast, exact runes, landing),
-- staged in setup (magic 45; 3x Camelot = 15 air + 3 law, 1x Varrock = 3 air + 1 fire
-- + 1 law). What stays a goto_tile is a hop between two open tiles outdoors.
--   * Camelot: the courtyard gate kr_camelot_metalgateclosedr 2758,3482 (north wall of
--     its tile; the only way in on foot), the castle's large doors kr_cam_doubledoorr
--     2758,3503 (north wall), the wooden stairs 2750,3509 (maplink.dbrow 0_42_54_63_52
--     -> 1_42_54_63_57), Lancelot's double door kr_cam_doubledoorl 2761,3505,1, the
--     tower's two kr_cam_poshdoor 2766,3503 and 2766,3496, the ladders 2769,3493,0 and
--     2767,3491,1 (no maplink row: [proc,climb] moves one plane on the approach tile).
--   * Keep Le Faye: entered by Arhein's crate (quest_arthur_crate.rs2: the landing is
--     graded), the back door castledoubledoorr 2776,3401 (west wall), the two stairs
--     (quest_arthur_keep_stairs.rs2 telejumps), and LEFT by the front door
--     lefayeunopenabledoorl 2763,3402, which opens from inside only
--     ([label,keep_lefaye_door_open] -> ~keep_lefaye_walk_door teleports onto its tile).
--   * Catherby's repellent house poshdoor 2806,3452 (west wall); Varrock's Zamorak
--     temple fai_varrock_poor_door_flipped 3255,3388 (east wall); Taverley's east
--     members' gate membergater 2935,3450 (walk-through, the only way on foot to Port
--     Sarim: reach.py NEEDS-DOOR at margins 30, 80 and 160).
--
-- Three rules the first pilot pass broke -- read before touching this file:
-- (a) "blocked" means a t.blocked("...") row followed by return -- a file
--     that runs on to expect_complete() after a failure is rejected.
-- (b) a talk_to/click answering screen_position or not_visible means you
--     are not standing near the target -- fix the goto, not the verb.
-- (c) never add a fixture or a helper file -- this quest file is the only
--     file you edit.

return {
    id = "arthur",
    fixture = "fresh_lumbridge.ini",
    max_frames = 300000,
    setup = {
        "::clearinv",
        "::setlevel attack 99",
        "::setlevel strength 99",
        "::setlevel defence 99",
        "::setlevel hitpoints 99",
        "::setlevel magic 45",
        "::give rune_scimitar 1",
        "::wield rune_scimitar",
        "::give lobster 17",
        "::give coins 1000",
        "::give bread 1",
        "::give airrune 18",
        "::give lawrune 4",
        "::give firerune 1",
    },

    run = function(t)
        local function tile_text(r, tl)
            if r == "ok" and type(tl) == "table" then
                return tl.x .. "," .. tl.z .. "," .. tl.level
            end
            return tostring(r)
        end

        -- One walk on one floor, graded on the exact tile it reached.
        local function hop(name, x, z, level)
            local wr, wd = t.player.walk_to(x, z)
            local r, tl = t.world.tile()
            if not (r == "ok" and tl.x == x and tl.z == z) then
                t.ticks(2)
                wr, wd = t.player.walk_to(x, z)
                r, tl = t.world.tile()
            end
            t.check(name, r == "ok" and tl.x == x and tl.z == z and tl.level == level,
                "walk_to " .. x .. "," .. z .. " -> " .. tostring(wr) .. " (" .. tostring(wd) .. "); at "
                    .. tile_text(r, tl) .. " (want " .. x .. "," .. z .. "," .. level .. ")")
        end

        -- A dialogue driven page by page; picks are taken in order at each options page.
        local function dialog(name, picks)
            local pi, trail = 1, ""
            for _ = 1, 8 do
                if t.chat.kind() ~= "none" then break end
                t.ticks(1)
            end
            for _ = 1, 12 do
                local dr, dk = t.chat.drain({ stop_at = "options", max_pages = 60 })
                trail = trail .. "drain->" .. tostring(dr) .. "/" .. tostring(dk) .. " | "
                if t.chat.kind() ~= "options" then break end
                local sel = picks[pi]
                pi = pi + 1
                if sel == nil then
                    t.check(name .. ".choose", false, "no pick left for an options page; " .. trail)
                    break
                end
                local cr, cd = t.chat.choose(sel)
                trail = trail .. "choose:" .. sel .. "=" .. tostring(cr) .. " | "
                if cr ~= "ok" then
                    t.check(name .. ".choose", false, tostring(cr) .. " " .. tostring(cd))
                    break
                end
            end
            t.check(name, pi - 1 == #picks, "picks used " .. (pi - 1) .. " of " .. #picks .. "; " .. trail:sub(1, 500))
            t.ticks(2)
        end

        local function excalibur_bits()
            local vr, vv = t.var.server("varp5761_excalibur_components_progress")
            return vr == "ok" and type(vv) == "number", vv
        end

        -- Fights: every kill wait eats a lobster under 55 and its detail carries
        -- "lowest hp N/99"; a fight's margin row needs the lowest reading >= 25
        -- (a quarter of 99) AND lobsters left.
        local EAT = { eat = { item = "lobster", below = 55 } }
        local function kill_wait(name, fight)
            local r, d = t.npc.await_dead_engaged(300, 12, EAT)
            t.step(name, r == "ok" and "PASS" or "FAIL", tostring(r) .. " " .. tostring(d))
            local low = tonumber(string.match(tostring(d), "lowest hp (%d+)/") or "")
            if low ~= nil and (fight.low == nil or low < fight.low) then
                fight.low = low
            end
            fight.kills = fight.kills + 1
        end
        local function margin_row(name, fight, what)
            local fr, food = t.inv.count("lobster")
            t.check(name, fight.low ~= nil and fight.low >= 25 and fr == "ok" and food >= 1,
                what .. ": " .. fight.kills .. " fight(s), lowest hp " .. tostring(fight.low)
                    .. "/99, lobsters left " .. tostring(food) .. " of 17 staged (" .. tostring(fr)
                    .. ") (margin: lowest hp >= 25, a quarter of 99, AND food left)")
        end
        local function clear_knights(prefix, fight)
            for i = 1, 4 do
                local pr = t.npc.await_present("renegade_knight", 6, 3)
                if pr ~= "ok" then break end
                local ra, da = t.player.attack("renegade_knight", 2, 10)
                t.check("knight-attack-" .. prefix .. "_" .. i, ra == "ok" or ra == "timeout", tostring(ra) .. " " .. tostring(da))
                kill_wait("knight-dead-" .. prefix .. "_" .. i, fight)
            end
        end

        -- Camelot: the courtyard gate (north wall of 2757-2758,3482) and the castle's
        -- large doors (north wall of 2757-2758,3503). Each trip presses both.
        local function camelot_gate(name, inward)
            if inward then
                t.exec(name, t.player.pass_door, { closed = "kr_camelot_metalgateclosedr", open = "kr_camelot_metalgateopenr",
                    at = { 2758, 3482, 0 }, near = { 2758, 3482 }, far = { 2758, 3483 } })
            else
                t.exec(name, t.player.pass_door, { closed = "kr_camelot_metalgateclosedr", open = "kr_camelot_metalgateopenr",
                    at = { 2758, 3482, 0 }, near = { 2758, 3483 }, far = { 2758, 3481 } })
            end
        end
        local function castle_door(name, inward)
            if inward then
                t.exec(name, t.player.pass_door, { closed = "kr_cam_doubledoorr", open = "kr_cam_doubledoorr_open",
                    at = { 2758, 3503, 0 }, near = { 2758, 3503 }, far = { 2758, 3504 } })
            else
                t.exec(name, t.player.pass_door, { closed = "kr_cam_doubledoorr", open = "kr_cam_doubledoorr_open",
                    at = { 2758, 3503, 0 }, near = { 2758, 3504 }, far = { 2758, 3502 } })
            end
        end
        local function camelot_teleport(name)
            t.player.teleport_cast("camelot_teleport", { 2757, 3478, 0 }, { name = name,
                runes = { { "airrune", 5 }, { "lawrune", 1 } }, where = "Camelot, tele_coord 0_43_54_5_22" })
        end

        local bind_result, bind_detail = t.quest.bind({
            varp = "varp14_arthur",
            constants = {
                not_started = 0, started = 1, spoken_gawain = 2, spoken_lancelot = 3,
                spoken_morgan_lefaye = 4, excalibur_bound = 5, freed_merlin = 6, complete = 7,
            },
            row = "quest_merlinscrystal",
            display = "Merlin's Crystal",
            points = 6,
        })
        t.step("quest.bind", bind_result == "ok" and "PASS" or "FAIL", bind_detail)

        -- startQuest: a Camelot Teleport from Lumbridge lands south of the courtyard
        -- gate; through the gate and the castle's large doors to King Arthur.
        camelot_teleport("startQuest.camelotTeleport")
        camelot_gate("startQuest.courtyardGateIn", true)
        castle_door("startQuest.castleDoorIn", true)
        hop("startQuest.toArthur", 2764, 3513, 0)
        t.exec("startQuest", t.player.talk_to, "king_arthur", 1)
        dialog("startQuest-dialog", { "/Knight of the Round Table/" })
        t.ticks(2)
        t.exec("quest.stage.started", t.quest.expect_stage, "started")

        -- talkToGawain: the same hall
        hop("talkToGawain.walk", 2763, 3505, 0)
        t.exec("talkToGawain", t.player.talk_to, "sir_gawain", 1)
        dialog("talkToGawain-dialog", { "/Do you know how Merlin got trapped/", "/Thank you for the information/" })
        t.ticks(2)
        t.exec("quest.stage.spoken_gawain", t.quest.expect_stage, "spoken_gawain")

        -- goUpstairsInCamelot (maplink 0_42_54_63_52 -> 1_42_54_63_57), Lancelot's double door
        hop("goUpstairsInCamelot.toStairs", 2751, 3508, 0)
        t.exec("goUpstairsInCamelot", t.player.climb, { loc = "kr_cam_woodenstairs", op = 1, op_name = "Climb-up",
            at = { 2750, 3509, 0 }, src = { 2751, 3508 }, dest = { 2751, 3513, 1 } })
        t.exec("talkToLancelot.doorIn", t.player.pass_door, { closed = "kr_cam_doubledoorl", open = "kr_cam_doubledoorl_open",
            at = { 2761, 3505, 1 }, near = { 2761, 3505 }, far = { 2761, 3506 } })
        hop("talkToLancelot.walk", 2759, 3512, 1)
        t.exec("talkToLancelot", t.player.talk_to, "sir_lancelot", 1)
        dialog("talkToLancelot-dialog", { "/Any ideas on how to get into Morgan/" })
        t.ticks(2)
        t.exec("quest.stage.spoken_lancelot", t.quest.expect_stage, "spoken_lancelot")

        -- goBackDownStairsCamelot, out of the castle and the courtyard, to Catherby
        t.exec("talkToLancelot.doorOut", t.player.pass_door, { closed = "kr_cam_doubledoorl", open = "kr_cam_doubledoorl_open",
            at = { 2761, 3505, 1 }, near = { 2761, 3506 }, far = { 2761, 3505 } })
        hop("goBackDownStairsCamelot.toStairs", 2751, 3513, 1)
        t.exec("goBackDownStairsCamelot", t.player.climb, { loc = "kr_cam_woodenstairstop", op = 1, op_name = "Climb-down",
            at = { 2750, 3511, 1 }, src = { 2751, 3513 }, dest = { 2751, 3508, 0 } })
        castle_door("hideInArheinCrate.castleDoorOut", false)
        camelot_gate("hideInArheinCrate.courtyardGateOut", false)

        -- hideInArheinCrate (behind the Candle Maker's shop; open ground)
        t.exec("goto-hideInArheinCrate", t.player.goto_tile, 2801, 3441, 0)
        t.exec("hideInArheinCrate", t.player.click_loc, "merlincrate_empty", 2)

        t.exec("hideInArheinCrate-dialog", t.chat.play, {
            "mesbox:The crate is empty",
            "choose:Yes.",
            "mesbox:You climb inside the crate",
            "mesbox:You wait.",
            "mesbox:And wait...",
            "mesbox:And wait...",
            "mesbox:You hear voices outside the crate",
            "mesbox:Yeah, I think so. Pack it aboard",
            "mesbox:You feel the crate being lifted",
            "mesbox:Quit your whining",
            "mesbox:being put down inside the ship",
        })
        -- the ship's "You wait..." / "And wait..." pages repeat earlier pages byte for byte: clicked through unphotographed
        for i = 1, 2 do
            t.ticks(2)
            local cr, cd = t.chat.continue_()
            t.step("hideInArheinCrate-wait" .. i, cr == "ok" and "PASS" or "FAIL", tostring(cr) .. " " .. tostring(cd))
        end
        t.exec("hideInArheinCrate-dialog-2", t.chat.play, {
            "mesbox:Casting off",
            "mesbox:the ship start to move",
            "mesbox:out at sea",
            "mesbox:The ship comes to a stop",
            "mesbox:Unload Mordred",
            "mesbox:You feel the crate being lifted.",
            "mesbox:mumbling outside the crate",
            "mesbox:if....MY ship",
            "mesbox:You feel the crate being put down.",
            "choose:Yes.",
            "mesbox:You climb out of the crate",
        })
        t.ticks(3)
        do
            local r, tile = t.world.tile()
            t.check("crate.arrived_keep", r == "ok" and tile.x == 2778 and tile.z == 3401 and tile.level == 0,
                "tile " .. tile_text(r, tile) .. " (want 2778,3401,0: the crate's Keep Le Faye landing)")
        end

        -- Keep Le Faye: the back door (west wall of 2776,3401), goToFirstFloor, goToSecondFloor
        -- (quest_arthur_keep_stairs.rs2 telejumps: 0_43_53_17_12 -> 1_43_53_17_15, 1_43_53_17_6 -> 2_43_53_17_9)
        local keep_fight = { kills = 0 }
        t.exec("keep-door", t.player.pass_door, { closed = "castledoubledoorr", open = "opencastledoubledoorr",
            at = { 2776, 3401, 0 }, near = { 2776, 3401 }, far = { 2775, 3401 } })
        clear_knights("k0", keep_fight)
        t.exec("goToFirstFloor", t.player.climb, { loc = "stairs", op = 1, op_name = "Climb-up",
            at = { 2769, 3404, 0 }, dest = { 2769, 3407, 1 } })
        clear_knights("k1", keep_fight)
        t.exec("goToSecondFloor", t.player.climb, { loc = "stairs", op = 1, op_name = "Climb-up",
            at = { 2769, 3398, 1 }, dest = { 2769, 3401, 2 } })
        clear_knights("k2", keep_fight)
        margin_row("keep.knights.margin", keep_fight, "renegade knights on the Keep's three floors")

        -- attackMordred: a real fight (combat_stats.generated.npc [sir_mordred]: 38 hp,
        -- 33 att/str/def); the killing blow opens Morgan's dialogue
        local mordred_fight = { kills = 0 }
        t.exec("mordred-present", t.npc.await_present, "sir_mordred", 15, 20)
        do
            local ra, da
            for _ = 1, 5 do
                ra, da = t.player.attack("sir_mordred", 2, 10)
                if not (type(da) == "string" and da:find("already under attack", 1, true)) then break end
                t.ticks(10)
            end
            t.step("attackMordred", ra == "ok" and "PASS" or "FAIL", tostring(ra) .. " " .. tostring(da))
            local kind, rounds = "none", 0
            while rounds < 120 do
                rounds = rounds + 1
                t.ticks(2)
                local hr, hp = t.skill.read("hitpoints")
                if hr == "ok" and type(hp) == "table" and hp.level then
                    if mordred_fight.low == nil or hp.level < mordred_fight.low then
                        mordred_fight.low = hp.level
                    end
                    if hp.level < 55 then t.player.inv_op("lobster", 1) end
                end
                kind = t.chat.kind()
                if kind ~= "none" then break end
            end
            mordred_fight.kills = 1
            t.check("mordred.fight_ended_in_dialogue", kind ~= "none", "chat.kind=" .. tostring(kind) .. " after " .. rounds .. " rounds of 2 ticks")
        end
        dialog("talkToMorgan-dialog", { "/Tell me how to untrap Merlin/", "/OK I will go do all that/" })
        t.ticks(2)
        t.exec("quest.stage.spoken_morgan_lefaye", t.quest.expect_stage, "spoken_morgan_lefaye")
        margin_row("attackMordred.margin", mordred_fight, "Sir Mordred (level 39), hitpoints sampled every 2 ticks")

        -- climbDownFaye2, climbDownFaye1 (telejumps 2_43_53_17_7 -> 1_43_53_17_5,
        -- 1_43_53_17_13 -> 0_43_53_17_11), out by the front door: it opens from inside
        -- only and ~keep_lefaye_walk_door puts the player on its own tile, outside.
        t.exec("climbDownFaye2", t.player.climb, { loc = "stairstop", op = 1, op_name = "Climb-down",
            at = { 2769, 3399, 2 }, dest = { 2769, 3397, 1 } })
        t.exec("climbDownFaye1", t.player.climb, { loc = "stairstop", op = 1, op_name = "Climb-down",
            at = { 2769, 3405, 1 }, dest = { 2769, 3403, 0 } })
        t.exec("getBatBones.frontDoorOut", t.player.cross_gate, { loc = "lefayeunopenabledoorl", at = { 2763, 3402, 0 },
            near = { 2764, 3402 }, far_ok = function(tl) return tl.x <= 2763 end,
            far_desc = "outside Keep Le Faye's front door, x <= 2763" })

        -- getBatBones: kill a giant bat outside the Keep and take its bones
        local bat_fight = { kills = 0 }
        hop("getBatBones.walk", 2759, 3401, 0)
        t.exec("bat-present", t.npc.await_present, "bat", 10, 20)
        do
            local ra, da = t.player.attack("bat", 2, 10)
            t.check("getBatBones-attack", ra == "ok", tostring(ra) .. " " .. tostring(da))
        end
        kill_wait("getBatBones", bat_fight)
        margin_row("getBatBones.margin", bat_fight, "giant bat (level 27)")
        t.exec("bat-bones-take", t.player.click_obj, "bat_bones")
        t.exec("bat-bones-held", t.inv.await, "bat_bones", 1, 6)

        -- optionalGetRepellent: the insect repellent lies on the table of a house in north
        -- Catherby (poshdoor on the west wall of 2806,3452)
        t.exec("goto-optionalGetRepellent", t.player.goto_tile, 2805, 3452, 0)
        t.exec("optionalGetRepellent.houseDoorIn", t.player.pass_door, { closed = "poshdoor", open = "poshdooropen",
            at = { 2806, 3452, 0 }, near = { 2805, 3452 }, far = { 2806, 3452 } })
        t.exec("optionalGetRepellent", t.player.click_obj, "insect_repellent")
        t.exec("repellent-held", t.inv.await, "insect_repellent", 1, 6)
        t.exec("optionalGetRepellent.houseDoorOut", t.player.pass_door, { closed = "poshdoor", open = "poshdooropen",
            at = { 2806, 3452, 0 }, near = { 2806, 3452 }, far = { 2805, 3452 } })

        -- goReadMagicWords: Varrock Teleport, then into the Zamorak temple by its door
        -- (east wall of 3255,3388) and Check the altar
        t.player.teleport_cast("varrock_teleport", { 3213, 3424, 0 }, { name = "goReadMagicWords.varrockTeleport",
            runes = { { "firerune", 1 }, { "airrune", 3 }, { "lawrune", 1 } }, where = "Varrock square, tele_coord 0_50_53_13_32" })
        t.exec("goto-goReadMagicWords", t.player.goto_tile, 3255, 3389, 0)
        t.exec("goReadMagicWords.templeDoorIn", t.player.pass_door, { closed = "fai_varrock_poor_door_flipped",
            open = "fai_varrock_poor_door_open_flipped", at = { 3255, 3388, 0 }, near = { 3255, 3388 }, far = { 3256, 3388 } })
        t.exec("goReadMagicWords", t.player.click_loc, "thrantaxaltar", 2)
        dialog("altar.inscription", {})
        do
            local ok, vv = excalibur_bits()
            t.check("altar.bit_set", ok and vv % 2 == 1, "chaosaltar bit (bit0) in " .. tostring(vv))
        end
        t.exec("goReadMagicWords.templeDoorOut", t.player.pass_door, { closed = "fai_varrock_poor_door_flipped",
            open = "fai_varrock_poor_door_open_flipped", at = { 3255, 3388, 0 }, near = { 3256, 3388 }, far = { 3255, 3388 } })

        -- talkToCandleMaker: Camelot Teleport back, then over open ground to Catherby;
        -- ask for a black candle (toggles the blackcandle bit)
        camelot_teleport("talkToCandleMaker.camelotTeleport")
        t.exec("goto-talkToCandleMaker", t.player.goto_tile, 2800, 3438, 0)
        t.exec("talkToCandleMaker", t.player.talk_to, "candle_maker", 1)
        dialog("candle.ask", { "/Have you got any black candles/" })
        do
            local ok, vv = excalibur_bits()
            t.check("candle.bit_set", ok and math.floor(vv / 2) % 2 == 1, "blackcandle bit (bit1) in " .. tostring(vv))
        end

        -- bucket + tinderbox are bought at Arhein's store
        t.exec("goto-arhein", t.player.goto_tile, 2803, 3432, 0)
        t.exec("arhein-trade", t.shop.open, "arhein", 3, "arheinstore")
        t.exec("arhein-buy-bucket", t.shop.buy, "bucket_empty", 1)
        t.exec("arhein-buy-tinderbox", t.shop.buy, "tinderbox", 1)
        do local r, d = t.shop.close(); t.check("arhein-shop-close", r == "ok", tostring(r) .. ": " .. tostring(d)) end

        -- optionalUseRepellent: Use the repellent on a hive (bees.rs2 [label,pour_repellent_bees]
        -- sets %varp5759_beehive_free and keeps the repellent), then Use the bucket for the wax
        t.exec("goto-optionalUseRepellent", t.player.goto_tile, 2758, 3439, 0)
        do
            local hive = t.player.by_symbol("loc", "merlin_beehive")
            t.exec("optionalUseRepellent", t.player.use_on, "insect_repellent", hive)
            dialog("hive.repel", {})
            do
                local vr, vv = t.var.server("varp5759_beehive_free")
                t.check("hive.bees_left", vr == "ok" and vv == 1, "varp5759_beehive_free " .. tostring(vr) .. " " .. tostring(vv) .. " (want 1 after the repellent)")
            end
            t.exec("hive-bucket", t.player.use_on, "bucket_empty", hive)
            dialog("hive.wax", {})
        end
        t.exec("hive-wax-held", t.inv.await, "bucket_wax", 1, 6)
        do
            local br, bn = t.inv.count("bucket_empty")
            t.check("hive.bucket_spent", br == "ok" and bn == 0, "bucket_empty " .. tostring(bn) .. " (" .. tostring(br) .. ") after the wax: want 0")
        end

        -- the candle maker swaps the wax for an unlit black candle
        t.exec("goto-candlemaker-handin", t.player.goto_tile, 2800, 3438, 0)
        t.exec("candlemaker-handin", t.player.talk_to, "candle_maker", 1)
        dialog("candle.handin", {})
        t.exec("candle-unlit-held", t.inv.await, "unlit_black_candle", 1, 6)
        do
            local ok, vv = excalibur_bits()
            t.check("candle.bit_cleared", ok and math.floor(vv / 2) % 2 == 0, "blackcandle bit (bit1) cleared in " .. tostring(vv))
        end

        -- lightCandle: Use the tinderbox on the unlit candle
        t.exec("lightCandle", t.player.use_item_on_item, "tinderbox", "unlit_black_candle")
        t.exec("candle-lit-held", t.inv.await, "lit_black_candle", 1, 6)
        do
            local ur, un = t.inv.count("unlit_black_candle")
            t.check("candle.unlit_gone", ur == "ok" and un == 0, "unlit_black_candle " .. tostring(un) .. " (" .. tostring(ur) .. ") after lighting: want 0")
        end

        -- talkToLadyOfLake: over White Wolf Mountain into Taverley (open ground: reach.py
        -- REACH closed-doors, no gate on the way)
        t.exec("goto-talkToLadyOfLake", t.player.goto_tile, 2925, 3405, 0)
        t.exec("talkToLadyOfLake", t.player.talk_to, "ladyofthelake", 1)
        dialog("talkToLadyOfLake-dialog", { "/I seek the sword Excalibur/" })
        do
            local ok, vv = excalibur_bits()
            t.check("lady.started_bit", ok and math.floor(vv / 4) % 2 == 1, "excalibur_started bit (bit2) in " .. tostring(vv))
        end

        -- enterSarimShopAndTalk: out of Taverley by the east members' gate (walk-through,
        -- gates.rs2 [label,member_fencegate_try]), then on open ground to Port Sarim
        t.exec("goto-enterSarimShopAndTalk.gate", t.player.goto_tile, 2932, 3450, 0)
        t.exec("enterSarimShopAndTalk.memberGateOut", t.player.cross_gate, { loc = "membergater", at = { 2935, 3450, 0 },
            near = { 2934, 3450 }, far_ok = function(tl) return tl.x >= 2936 end,
            far_desc = "out of Taverley, x >= 2936", far = { 2937, 3450 } })
        t.exec("goto-enterSarimShopAndTalk", t.player.goto_tile, 3018, 3246, 0)
        t.exec("enterSarimShopAndTalk", t.player.click_loc, "jewellersdoor", 1)
        dialog("beggar.first", { "/No I don't have any bread/" })
        do
            local ok, vv = excalibur_bits()
            t.check("beggar.spoken_bit", ok and math.floor(vv / 8) % 2 == 1, "excalibur_spoken_beggar bit (bit3) in " .. tostring(vv))
        end

        -- The beggar's "no bread" branch walks the player THROUGH the door into the
        -- jeweller's (beggar.rs2 [label,ignore_lake_beggar] -> ~jewellers_walk_door; LostCity
        -- beggar.rs2:48-52 ~open_and_close_door does the same), and he stands outside.
        do
            local r, tl = t.world.tile()
            t.check("beggar.first.inside_shop", r == "ok" and tl.x <= 3015 and tl.level == 0,
                "tile " .. tile_text(r, tl) .. " (want inside the jeweller's, x <= 3015: the door walked us in)")
        end
        -- talkToBeggar with the bread: back out by the door (from inside it puts the player
        -- on its own tile 3016,3246, outside: ~jewellers_walk_door(false))
        t.exec("talkToBeggar.shopDoorOut", t.player.cross_gate, { loc = "jewellersdoor", at = { 3016, 3246, 0 },
            near = { 3015, 3246 }, far_ok = function(tl) return tl.x >= 3016 end,
            far_desc = "outside the jeweller's, x >= 3016" })
        t.exec("talkToBeggar", t.player.talk_to, "lake_beggar", 1)
        dialog("talkToBeggar-dialog", { "/Yes, here you go/" })
        t.exec("excalibur-held", t.inv.await, "excalibur", 1, 6)
        do
            local br, bn = t.inv.count("bread")
            t.check("beggar.bread_given", br == "ok" and bn == 0, "bread " .. tostring(bn) .. " (" .. tostring(br) .. ") after the beggar: want 0")
        end
        do
            local ok, vv = excalibur_bits()
            t.check("beggar.rewarded_bit", ok and math.floor(vv / 16) % 2 == 1, "excalibur_rewarded bit (bit4) in " .. tostring(vv))
        end

        -- returnToCamelot: Camelot Teleport, then through the courtyard gate
        camelot_teleport("returnToCamelot.camelotTeleport")
        camelot_gate("returnToCamelot", true)

        -- goStandInStar (inside the courtyard), dropBatBones, sayWords
        t.exec("goto-goStandInStar", t.player.goto_tile, 2779, 3515, 0)
        t.exec("dropBatBones", t.player.inv_op, "bat_bones", 5)
        dialog("sayWords", { "/Snarthon Candtrick Termanto/" })
        t.ticks(2)
        t.exec("quest.stage.excalibur_bound", t.quest.expect_stage, "excalibur_bound")
        do
            -- [opheld5,bat_bones] in the star summons Thrantax and never deletes the bones
            -- (thrantax_altar.rs2:29-79; LostCity quest_arthur.rs2:150 likewise): they stay held
            local br, bn = t.inv.count("bat_bones")
            t.check("dropBatBones.kept", br == "ok" and bn == 1, "bat_bones " .. tostring(bn) .. " (" .. tostring(br) .. ") after the drop in the star: want 1 (the content keeps them)")
        end
        do
            local ok, vv = excalibur_bits()
            t.check("bound.bits_cleared", ok and vv % 4 == 0, "chaosaltar+blackcandle bits cleared in " .. tostring(vv))
        end

        -- goUpLadder1Camelot, goUpLadder2Camelot: into the castle, through the hall's east
        -- door (north wall of 2766,3503) and the tower door (south wall of 2766,3496), up two
        -- ladders with no maplink row ([proc,climb]: one plane on the approach tile)
        castle_door("goUpLadder1Camelot.castleDoorIn", true)
        t.exec("goUpLadder1Camelot.hallDoorIn", t.player.pass_door, { closed = "kr_cam_poshdoor", open = "kr_cam_poshdoor_open",
            at = { 2766, 3503, 0 }, near = { 2766, 3504 }, far = { 2766, 3503 } })
        t.exec("goUpLadder1Camelot.towerDoorIn", t.player.pass_door, { closed = "kr_cam_poshdoor", open = "kr_cam_poshdoor_open",
            at = { 2766, 3496, 0 }, near = { 2766, 3496 }, far = { 2766, 3495 } })
        t.exec("goUpLadder1Camelot", t.player.climb, { loc = "kr_cam_ladder", op = 1, op_name = "Climb-up",
            at = { 2769, 3493, 0 }, dest = { 2769, 3493, 1 }, slack = 1 })
        t.exec("goUpLadder2Camelot", t.player.climb, { loc = "kr_cam_ladder", op = 1, op_name = "Climb-up",
            at = { 2767, 3491, 1 }, dest = { 2767, 3491, 2 }, slack = 1 })

        -- smashCrystal: Use Excalibur on the crystal
        do
            local crystal = t.player.by_symbol("loc", "merlins_crystal")
            t.exec("smashCrystal", t.player.use_on, "excalibur", crystal)
        end
        dialog("smashCrystal-dialog", {})
        t.ticks(2)
        t.exec("quest.stage.freed_merlin", t.quest.expect_stage, "freed_merlin")

        -- goDownLadder2Camelot, goDownLadder1Camelot, back out of the tower to King Arthur
        t.exec("goDownLadder2Camelot", t.player.climb, { loc = "kr_cam_laddertop", op = 1, op_name = "Climb-down",
            at = { 2767, 3491, 2 }, dest = { 2767, 3491, 1 }, slack = 1 })
        t.exec("goDownLadder1Camelot", t.player.climb, { loc = "kr_cam_laddertop", op = 1, op_name = "Climb-down",
            at = { 2769, 3493, 1 }, dest = { 2769, 3493, 0 }, slack = 1 })
        t.exec("finishQuest.towerDoorOut", t.player.pass_door, { closed = "kr_cam_poshdoor", open = "kr_cam_poshdoor_open",
            at = { 2766, 3496, 0 }, near = { 2766, 3495 }, far = { 2766, 3496 } })
        t.exec("finishQuest.hallDoorOut", t.player.pass_door, { closed = "kr_cam_poshdoor", open = "kr_cam_poshdoor_open",
            at = { 2766, 3503, 0 }, near = { 2766, 3503 }, far = { 2766, 3504 } })
        hop("finishQuest.toArthur", 2764, 3513, 0)
        local reward_excalibur_before_result, reward_excalibur_before = t.inv.count("excalibur")
        t.exec("finishQuest", t.player.talk_to, "king_arthur", 1)
        dialog("finishQuest-dialog", {})
        t.ticks(6)
        t.quest.expect_complete()

        local reward_excalibur_after_result, reward_excalibur_after = t.inv.count("excalibur")
        t.check("reward.excalibur", reward_excalibur_before_result == "ok" and reward_excalibur_after_result == "ok" and reward_excalibur_after == 1,
            string.format("excalibur %s -> %s (Quest Helper: 1 item, Excalibur kept)", tostring(reward_excalibur_before), tostring(reward_excalibur_after)))

        t.finish(0)
    end,
}
